// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public {
        vm.deal(address(this), 2 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }
    function testFuzz_property(uint256 payment, bytes32 hash) public {
        payment = bound(payment, 0, 2 ether);
        vm.assume(payment != 1 ether);

        address actor = address(0x1000);
        vm.deal(actor, payment);

        uint256 balBefore = address(c).balance;
        bool ok;
        vm.prank(actor);
        try c.lockInGuess{value: payment}(hash) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 balAfter = address(c).balance;

        if (ok) {
            assertTrue(balAfter == balBefore + 1 ether);
        }
    }
}
